// KilasFlow-authored control body: lodash, Luxon, console and both roots.
const _ = require('lodash');
const { DateTime } = require('luxon');
const out = [];
for (const item of $input.all()) {
  const order = item.json;
  const total = _.round(_.sumBy(order.lines, (line) => line.qty * line.price), 2);
  const placed = DateTime.fromISO(order.placedAt, { zone: 'America/New_York' });
  console.log('scored', order.orderId, total);
  out.push({ json: { orderId: order.orderId, customer: _.startCase(order.customer), total, local: placed.toFormat('yyyy-LL-dd HH:mm ZZZZ'), weekday: placed.weekdayLong, skus: _.uniq(order.lines.map((line) => line.sku)).sort() } });
}
return out;

// KilasFlow-authored control body: per-item roots, $('Node'), Buffer and crypto.
const crypto = require('crypto');
const first = $('Orders').first().json;
const text = `${$json.orderId}:${$json.total}:${first.orderId}`;
const digest = crypto.createHash('sha256').update(text).digest('hex');
const mac = crypto.createHmac('sha256', 'control-key').update(text).digest('base64');
return { json: { ...$json, index: $itemIndex, token: Buffer.from(text).toString('base64'), hex: Buffer.from(text, 'utf8').toString('hex').slice(0, 16), digest, mac, paired: $('Orders').item.json.orderId } };
